# Generated by Claudian.
"""Jarvis CLI entry point.

Subcommands:
    ask <text>            Run text through the same skill router as voice.
    status                Show provider, skills, memory stats.
    skills                List available skills with priority + description.
    memory add <text>     Store a fact in long-term memory.
    memory list           Show recent stored facts.
    memory recall <q>     Search facts by keyword.
    doctor                Quick health check (mic, WhatsApp, Ollama, Groq).

Designed for fast keyboard-only use — no auth, no shell history pollution,
no waiting on TTS.  Use this when you want Jarvis to think but not speak.
"""

from __future__ import annotations

import argparse
import asyncio
import os
import sys

# Make sure project root is on sys.path so `from skills import ...` works
# when this is invoked as `python3 -m cli` from the project dir.
_HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, os.path.dirname(_HERE))


def _build_parser() -> argparse.ArgumentParser:
    p = argparse.ArgumentParser(prog="jarvis", description="Jarvis CLI")
    sub = p.add_subparsers(dest="command", required=True)

    # ask
    ask = sub.add_parser("ask", help="Run text through the skill router")
    ask.add_argument("text", nargs="+", help="What to ask Jarvis")

    # status
    sub.add_parser("status", help="Show Jarvis status")

    # skills
    sub.add_parser("skills", help="List available skills")

    # memory
    mem = sub.add_parser("memory", help="Memory operations")
    mem_sub = mem.add_subparsers(dest="memory_cmd", required=True)
    mem_add = mem_sub.add_parser("add", help="Store a fact")
    mem_add.add_argument("text", nargs="+", help="The fact to remember")
    mem_sub.add_parser("list", help="List recent facts")
    mem_recall = mem_sub.add_parser("recall", help="Search facts by keyword")
    mem_recall.add_argument("query", nargs="+", help="Keyword(s) to search")

    # doctor
    sub.add_parser("doctor", help="Health check")

    return p


# ── Subcommand handlers ──────────────────────────────────────────────────────

def _cmd_ask(text: str) -> int:
    from core.command_router import CommandRouter
    router = CommandRouter()
    # route() returns (reply, should_shutdown, already_spoken, confirm).
    # This unpacked two values and had been raising ValueError since the
    # third was added — the CLI was simply broken.
    reply, _shutdown, _spoken, confirm = asyncio.run(router.route(text))
    if confirm is not None:
        # Text CLI has no confirmation loop; state the gate rather than
        # silently doing nothing, and never auto-approve.
        reply = f"{reply} (Confirmation is only available in voice mode.)"
    print(reply)
    return 0


def _cmd_status() -> int:
    from config import settings
    from memory import get_memory
    from skills._registry import get_registry

    reg = get_registry()
    mem = get_memory()
    facts = len(mem.all_facts(limit=10000))
    events_today = len(mem.today_events())

    print("Jarvis status")
    print(f"  LLM provider:     {settings.LLM_PROVIDER}")
    if settings.LLM_PROVIDER == "groq":
        print(f"  Groq key set:     {bool(settings.GROQ_API_KEY)}")
        print(f"  Groq chat model:  {settings.GROQ_CHAT_MODEL}")
    else:
        print(f"  Ollama host:      {settings.OLLAMA_HOST}")
        print(f"  Ollama model:     {settings.OLLAMA_MODEL}")
    print(f"  Skills loaded:    {len(reg.all_skills())}")
    print(f"  Facts stored:     {facts}")
    print(f"  Events today:     {events_today}")
    return 0


def _cmd_skills() -> int:
    from skills._registry import get_registry
    reg = get_registry()
    for s in reg.all_skills():
        print(f"  [{s.priority:3d}] {s.name:20s} — {s.description}")
    return 0


def _cmd_memory_add(text: str) -> int:
    from memory import get_memory
    fact_id = get_memory().remember(text)
    print(f"Stored fact #{fact_id}: {text}")
    return 0


def _cmd_memory_list() -> int:
    from memory import get_memory
    facts = get_memory().all_facts(limit=20)
    if not facts:
        print("(no facts stored yet)")
        return 0
    for f in facts:
        ts = f.created_at[:10]
        print(f"  #{f.id:4d}  {ts}  {f.text}")
    return 0


def _cmd_memory_recall(query: str) -> int:
    from memory import get_memory
    facts = get_memory().recall(query, limit=10)
    if not facts:
        print(f"(nothing matched '{query}')")
        return 1
    for f in facts:
        ts = f.created_at[:10]
        print(f"  #{f.id:4d}  {ts}  {f.text}")
    return 0


def _cmd_doctor() -> int:
    from config import settings
    print("Doctor:")
    # 1. PyAudio / mic
    try:
        import speech_recognition as sr
        sr.Microphone.list_microphone_names()
        print("  mic              : OK")
    except Exception as e:
        print(f"  mic              : FAIL ({e})")
    # 2. WhatsApp.app
    try:
        from integrations.whatsapp.whatsapp_desktop import WhatsAppDesktop
        ok = WhatsAppDesktop().is_available()
        print(f"  WhatsApp.app     : {'OK' if ok else 'NOT INSTALLED'}")
    except Exception as e:
        print(f"  WhatsApp.app     : FAIL ({e})")
    # 3. LLM provider
    if settings.LLM_PROVIDER == "ollama":
        try:
            from ai.local_llm import OllamaClient
            ok = OllamaClient().is_available()
            print(f"  Ollama @ {settings.OLLAMA_HOST}: {'OK' if ok else 'UNREACHABLE'}")
        except Exception as e:
            print(f"  Ollama           : FAIL ({e})")
    else:
        print(f"  Groq key set     : {'OK' if settings.GROQ_API_KEY else 'MISSING'}")
    # 4. Memory DB
    try:
        from memory import get_memory
        m = get_memory()
        m.all_facts(limit=1)
        print("  Memory DB        : OK")
    except Exception as e:
        print(f"  Memory DB        : FAIL ({e})")
    # 5. Skills load
    try:
        from skills._registry import get_registry
        n = len(get_registry().all_skills())
        print(f"  Skills           : OK ({n} loaded)")
    except Exception as e:
        print(f"  Skills           : FAIL ({e})")
    return 0


# ── Entry ────────────────────────────────────────────────────────────────────

def main(argv: list[str] | None = None) -> int:
    args = _build_parser().parse_args(argv)
    cmd = args.command

    if cmd == "ask":
        return _cmd_ask(" ".join(args.text))
    if cmd == "status":
        return _cmd_status()
    if cmd == "skills":
        return _cmd_skills()
    if cmd == "memory":
        if args.memory_cmd == "add":
            return _cmd_memory_add(" ".join(args.text))
        if args.memory_cmd == "list":
            return _cmd_memory_list()
        if args.memory_cmd == "recall":
            return _cmd_memory_recall(" ".join(args.query))
    if cmd == "doctor":
        return _cmd_doctor()
    return 1


if __name__ == "__main__":
    sys.exit(main())
